#include <stdio.h>
#include <string.h>
#include <stddef.h>

#define OUT_BUF_SIZE 1024

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode  = argv[1];
    const char *input = argv[2];
    char out[OUT_BUF_SIZE];
    size_t out_len = 0;

    if (strcmp(mode, "to_camel") == 0) {
        int capitalize_next = 0;
        for (size_t i = 0; input[i] && out_len < OUT_BUF_SIZE - 1; ++i) {
            char ch = input[i];
            if (ch == '_') {
                capitalize_next = 1;
                continue;
            }
            if (capitalize_next) {
                if ('a' <= ch && ch <= 'z')
                    ch = (char)(ch - ('a' - 'A'));
                capitalize_next = 0;
            } else {
                if ('A' <= ch && ch <= 'Z')
                    ch = (char)(ch + ('a' - 'A'));
            }
            out[out_len++] = ch;
        }
        out[out_len] = '\0';
        puts(out);
    }
    else if (strcmp(mode, "to_snake") == 0) {
        for (size_t i = 0; input[i] && out_len < OUT_BUF_SIZE - 1; ++i) {
            char ch = input[i];
            if ('A' <= ch && ch <= 'Z') {
                if (i != 0 && out_len < OUT_BUF_SIZE - 1)
                    out[out_len++] = '_';
                ch = (char)(ch + ('a' - 'A'));
            }
            out[out_len++] = ch;
        }
        out[out_len] = '\0';
        puts(out);
    }
    else {
        puts("INVALID_MODE");
    }
    return 0;
}
